"""Random request generator for differential testing."""
import json, random, string

IDS = string.ascii_letters + string.digits + '_.-'

def rid(rng):
    return ''.join(rng.choice(IDS) for _ in range(rng.randint(1, 8)))

def make_kinds(rng, H):
    base = [rng.choice('KKKDZZD') for _ in range(H)]
    idxs = list(range(H)); rng.shuffle(idxs)
    base[idxs.pop()] = 'Q'; base[idxs.pop()] = 'T'
    if base.count('K') < 1:
        for i, c in enumerate(base):
            if c == 'Z':
                base[i] = 'K'; break
    while 4 + base.count('D') >= H:
        for i, c in enumerate(base):
            if c == 'D':
                base[i] = 'K'; break
    return ''.join(base)

def make_flow(rng, nodes, fid):
    N = rng.randint(2, min(9, len(nodes)))
    path = rng.sample(nodes, N)
    H = rng.choice([8, 9, 12, 16, 20, 32]) if rng.random() < 0.7 else rng.randint(8, 256)
    tmpl = ''.join('%02x' % rng.randrange(256) for _ in range(H))
    kinds = make_kinds(rng, H)
    f = {'id': fid, 'path': path, 'template': tmpl, 'kinds': kinds}
    f['labels'] = [rng.choice([16, 17, 100, 1048575, rng.randint(16, 1048575)])
                   for _ in range(N)]
    return f

def header_for(rng, f, mode=None):
    H = len(f['kinds'])
    b = bytearray(rng.randrange(256) for _ in range(H))
    if mode is None:
        mode = rng.choice(['match','match','match','mismatch','qos','edge'])
    for i, c in enumerate(f['kinds']):
        if c == 'K' and mode != 'mismatch':
            b[i] = int(f['template'][2*i:2*i+2], 16)
        elif c == 'K' and mode == 'mismatch' and rng.random() < 0.5:
            b[i] = (int(f['template'][2*i:2*i+2], 16) ^ 0x5a) & 0xff
    q = f['kinds'].index('Q')
    if mode == 'qos':
        b[q] = rng.randint(8, 255)
    elif rng.random() < 0.85:
        b[q] = rng.randint(0, 7)
    t = f['kinds'].index('T')
    h = len(f['path']) - 1
    if mode == 'edge':
        b[t] = rng.choice([0, 1, 2, h, h+1, h+2, 255])
    else:
        b[t] = rng.choice([0, 1, 2, 3, h, h+1, h+2, 5, 9, 255, 64])
    return b.hex()

def payload_for(rng):
    if rng.random() < 0.15:
        return ''
    n = rng.choice([0, 1, 2, 4, 8, 16, 64, 2048, rng.randint(0, 300)])
    return ''.join('%02x' % rng.randrange(256) for _ in range(n))

def gen_replay(rng):
    nn = rng.randint(1, 10)
    nodes = [rid(rng) for _ in range(nn)]
    if len(set(nodes)) != nn:
        nodes = ['n%d' % i for i in range(nn)]
    caps = {n: rng.choice([0, 1, 1, 2, 3, 5, 512, rng.randint(0, 6)]) for n in nodes}
    nf = rng.randint(0, 6)
    flows = [make_flow(rng, nodes, 'f%d' % i if rng.random() < 0.9 else rid(rng))
             for i in range(nf)]
    ids = [f['id'] for f in flows]
    if len(set(ids)) != len(ids):
        flows, ids = [], []
    events = []
    for _ in range(rng.randint(0, 60)):
        r = rng.random()
        if r < 0.3 and flows:
            f = rng.choice(flows)
            events.append({'op': 'put', 'flow': f['id'], 'node': rng.choice(f['path'])})
        elif r < 0.5 and flows:
            events.append({'op': 'enable', 'flow': rng.choice(flows)['id']})
        elif r < 0.6 and flows:
            events.append({'op': 'disable', 'flow': rng.choice(flows)['id']})
        elif r < 0.65:
            events.append({'op': 'reset'})
        elif flows:
            f = rng.choice(flows)
            events.append({'op': 'packet', 'flow': f['id'],
                           'header': header_for(rng, f), 'payload': payload_for(rng)})
        else:
            events.append({'op': 'reset'})
    return {'mode': 'replay', 'capacities': caps, 'flows': flows, 'events': events}

def gen_plan(rng):
    nn = rng.randint(2, 6)
    nodes = ['n%d' % i for i in range(nn)]
    caps = {n: rng.choice([0, 1, 1, 2, 3, 512, rng.randint(0, 5)]) for n in nodes}
    nf = rng.randint(0, 8)
    flows = [make_flow(rng, nodes, 'f%d' % i) for i in range(nf)]
    for f in flows:
        del f['labels']
    offers = {}
    for f in flows:
        runs = []
        for _ in range(rng.randint(0, 6)):
            runs.append({'header': header_for(rng, f), 'count': rng.randint(1, 50)})
        offers[f['id']] = runs
    pinned = []
    if flows and rng.random() < 0.5:
        pinned = rng.sample([f['id'] for f in flows], rng.randint(1, min(3, len(flows))))
    return {'mode': 'plan', 'capacities': caps, 'flows': flows,
            'warmup': rng.choice([0, 0, 1, 2, 5, 20, 100]),
            'pinned': pinned, 'offers': offers}

if __name__ == '__main__':
    import sys
    seed = int(sys.argv[1]) if len(sys.argv) > 1 else 0
    mode = sys.argv[2] if len(sys.argv) > 2 else 'replay'
    rng = random.Random(seed)
    gen = gen_replay if mode == 'replay' else gen_plan
    sys.stdout.write(json.dumps(gen(rng)))
